/*
 * 【ことばクエスト ver1.2.1 PC｜日本語注記】
 * ファイル：shiba-burger-r4/scripts/shiba-model-inline.js
 * 役割：R4版柴犬の3Dモデル読み込み支援（生成データは編集しない）
 * 利用画面：shiba-burger-r4/index.html
 * 注意：※ 3D埋め込みデータ：内部の長い数値・文字列は編集しないでください。
 * 変更時：読み込むHTML・service-worker.js・docs/スクリプト読込順.mdも確認してください。
 */
/* Original Shiba Inu glTF bytes, no fetch required under file:// */
(function(){
const original="";
const NativeLoader=window.KQGLTFLoader;
if(!NativeLoader){console.warn("3Dを初期化できません。2Dクイズとして続行します。");return}
class OfflineShibaLoader extends NativeLoader {
load(url,onLoad,onProgress,onError){
 if(!/(?:^|\/)shiba-inu\.glb(?:[?#]|$)/.test(String(url)))return super.load(url,onLoad,onProgress,onError);
 try{const raw=atob(original),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);this.parse(bytes.buffer,"",onLoad,onError||((e)=>console.warn(e)));}
 catch(error){if(onError)onError(error);else console.warn(error)}return this;
}
loadAsync(url,onProgress){return new Promise((resolve,reject)=>this.load(url,resolve,onProgress,reject))}
}
window.KQGLTFLoader=OfflineShibaLoader;
})();
